const lockOrderItems = `-- name: LockOrderItems :many
SELECT id, uuid, order_id, organization_id, brand_id, product_id, quantity, meters, unit_price, price_source, recommended_price_snapshot, line_total, note, created_at, updated_at FROM order_items
WHERE order_id = $1
ORDER BY id
FOR UPDATE
`

func (q *Queries) LockOrderItems(ctx context.Context, orderID int64) ([]OrderItem, error) {
	rows, err := q.db.Query(ctx, lockOrderItems, orderID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OrderItem{}
	for rows.Next() {
		var i OrderItem
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrderID,
			&i.OrganizationID,
			&i.BrandID,
			&i.ProductID,
			&i.Quantity,
			&i.Meters,
			&i.UnitPrice,
			&i.PriceSource,
			&i.RecommendedPriceSnapshot,
			&i.LineTotal,
			&i.Note,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

